import { supabase } from "@/integrations/supabase/client";
import type { ApprovalKind, ApprovalQueueRow, ApprovalRpc } from "@/lib/approvals";

/**
 * Typed wrappers for two-administrator approval (D4 step 4). The RPCs are
 * newer than src/integrations/supabase/types.ts (regenerated by the
 * conductor after the paste), hence the one cast. Every call is the
 * signed-in administrator's own: the database decides who may do what.
 */
const db = supabase as any;

export interface ApprovalError { code: string; sqlstate: string; message: string; detail: string }

const CODES: Record<string, string> = {
  HC010: "reason_too_short", HC011: "token_stale", HC012: "confirm_required", HC013: "correction_reason_required",
  HC050: "guard_broken", HC060: "approval_required", HC061: "self_approval", HC062: "request_not_pending",
  HC063: "approval_already_pending", HC064: "request_expired", HC065: "approval_setting_locked",
  PGRST202: "guard_not_installed", "42883": "guard_not_installed", "42501": "forbidden", P0002: "not_found",
};

export function asApprovalError(e: any): ApprovalError {
  const sqlstate = String(e?.code ?? "");
  const code = sqlstate === "HC015" ? String(e?.message ?? "refused") : CODES[sqlstate] ?? "unexpected";
  return { code, sqlstate, message: String(e?.message ?? ""), detail: String(e?.details ?? e?.detail ?? "") };
}

type Res<T> = { data: T } | { error: ApprovalError };
async function call<T>(name: string, args: Record<string, unknown>): Promise<Res<T>> {
  const { data, error } = await db.rpc(name, args);
  if (error) return { error: asApprovalError(error) };
  return { data: data as T };
}

export const requestApproval = (kind: ApprovalKind, rpc: ApprovalRpc, params: Record<string, unknown>, token: string | null) =>
  call<{ request_id: string; status: string; reasons: string[]; expires_at: string }>("request_change_approval",
    { p_kind: kind, p_rpc: rpc, p_params: params, p_token: token });

export const previewRequest = (id: string) => call<any>("approval_request_preview", { p_request_id: id });
export const approveRequest = (id: string, token: string, note: string | null) =>
  call<any>("approve_change_request", { p_request_id: id, p_token: token, p_note: note });
export const rejectRequest = (id: string, note: string) => call<any>("reject_change_request", { p_request_id: id, p_note: note });
export const withdrawRequest = (id: string) => call<any>("withdraw_change_request", { p_request_id: id });
export const releaseOwnRequest = (id: string, token: string) => call<any>("release_own_request", { p_request_id: id, p_token: token });
export const acknowledgeReleased = (id: string, note: string | null) => call<any>("acknowledge_released_request", { p_request_id: id, p_note: note });
export const approvalStatus = () => call<any>("change_approval_status", {});
export const setApprovalSettings = (patch: Record<string, unknown>, reason: string) =>
  call<any>("set_change_approval_settings", { p_patch: patch, p_reason: reason });

export async function loadQueue(limit = 200): Promise<ApprovalQueueRow[]> {
  const { data, error } = await db.from("change_approval_queue").select("*").order("created_at", { ascending: false }).limit(limit);
  if (error) throw error;
  return (data ?? []) as ApprovalQueueRow[];
}
